export const GENERATED_NOTICE =
  '<!-- Generated by stackcrew. Do not edit: change stackcrew.json or .stackcrew/custom/, then run `stackcrew sync`. -->';

/**
 * Assemble a generated file: optional frontmatter block (ends with `---\n`),
 * then the notice on its own line, a blank line, then the body.
 */
export function withNotice(frontmatter, body) {
  return `${frontmatter ?? ''}${GENERATED_NOTICE}\n\n${body}`;
}
